let requests=[{id:'help-1',jobId:'RS-10482',mode:'sent',tech:'Maya Chen',store:'Downtown Store',status:'Open',created:'2025-04-28T10:24:00',comments:[{author:'You',text:'Need a second set of eyes on this screen issue. Touch isn’t responding in the top right corner.',time:'Apr 28, 10:24 AM'},{author:'Maya Chen',text:'On my way to take a look. I’ll check the display connector and run a quick test.',time:'Apr 28, 11:02 AM'}]}, {id:'help-2',jobId:'RS-10480',mode:'sent',tech:'Marcus Lee',store:'Riverside Store',status:'Waiting',created:'2025-04-28T08:24:00',comments:[{author:'You',text:'Could you help diagnose the drainage pump?',time:'Apr 28, 8:24 AM'}]}, {id:'help-3',jobId:'RS-10479',mode:'sent',tech:'Priya Shah',store:'Maple Grove Store',status:'Resolved',created:'2025-04-27T10:24:00',comments:[{author:'Priya Shah',text:'The battery connector has been reseated. Please run a discharge test.',time:'Apr 27, 10:24 AM'}]}, {id:'help-4',jobId:'RS-10468',mode:'sent',tech:'Daniel Park',store:'Downtown Store',status:'Completed',created:'2025-04-23T10:24:00',comments:[{author:'Daniel Park',text:'The wireless driver update fixed the issue.',time:'Apr 23, 10:24 AM'}]}, {id:'help-5',jobId:'RS-10481',mode:'received',tech:'Marcus Lee',store:'Riverside Store',status:'Open',created:'2025-04-28T09:18:00',comments:[{author:'Marcus Lee',text:'The laptop still will not power on. Could you check the board with me?',time:'Apr 28, 9:18 AM'}]}, {id:'help-6',jobId:'RS-10467',mode:'received',tech:'Taylor Kim',store:'Downtown Store',status:'Resolved',created:'2025-04-27T14:10:00',comments:[{author:'Taylor Kim',text:'Thanks for helping with the camera diagnostic!',time:'Apr 27, 2:10 PM'}]}];
