const job=()=>jobs.find(j=>j.id===route().id)||jobs[0];
function route(){const [page='dashboard',id]=location.hash.slice(1).split('/');return {page:page||'dashboard',id};}
function go(page,id){const hash='#'+page+(id?'/'+id:'');if(location.hash===hash){render();window.scrollTo(0,0)}else location.hash=hash;}
function badge(s,extra=''){return `<span class="badge ${s.toLowerCase().replaceAll(' ','-')} ${extra}">${esc(s)}</span>`}
function tile(n){return `<span class="icon-tile">${icon(n)}</span>`}
function deviceIcon(j){return `<span class="device-icon">${icon(j.type==='Phone'?'phone':j.type==='PC'?'pc':j.type==='Appliance'?'appliance':'tool')}</span>`}
function header(){return `<header class="header"><img class="logo" src="assets/favicon.svg" alt=""><div class="brand"><strong>FixFlow</strong><small>Repair. Resolve. Repeat.</small></div><button class="icon-button notification" data-action="notifications" aria-label="Notifications">${icon('bell')}</button><button class="profile" data-action="profile"><span class="avatar">JS</span><span><strong>Jordan Smith</strong><small>Technician</small></span><span aria-hidden="true">⌄</span></button></header>`}
function nav(active){return `<nav class="bottom-nav" aria-label="Main navigation">${[['dashboard','home','Dashboard'],['jobs','jobs','My Jobs'],['messages','chat','Messages'],['more','menu','More']].map(([id,i,label])=>`<button class="nav-item ${active===id?'active':''}" ${active===id?'aria-current="page"':''} data-action="nav" data-page="${id}">${icon(i)}${label}</button>`).join('')}</nav>`}
function pageHeading(title,subtitle){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div></div>`}
function devicePills(){return `<div class="pills" aria-label="Device type">${devices.map(d=>`<button class="pill ${state.device===d?'active':''}" data-action="device" data-value="${d}" aria-pressed="${state.device===d}">${d}</button>`).join('')}</div>`}
function jobRow(j,detailed=false){return `<button class="job-row ${detailed?'detailed':''}" data-action="job" data-id="${j.id}">${deviceIcon(j)}<span class="identity"><strong class="job-id">#${j.id}</strong><span class="job-device">${esc(j.device)}</span></span><span class="issue">${esc(j.issue)}${detailed&&j.label?`<br>${badge(j.label,j.label==='Parts ordered'?'label purple':'label')}`:''}</span>${detailed?`<span class="job-progress"><span class="progress-line"><span class="progress-track"><i style="width:${j.progress}%"></i></span>${j.progress}%</span><span class="badges">${badge(j.status)}${badge(j.priority)}</span><small class="updated">Updated ${esc(j.updated)}</small></span>`:`<span class="badges">${badge(j.priority)}${badge(j.status)}</span>`}<span class="chevron">›</span></button>`}
function dashboard(){const filtered=jobs.filter(j=>state.device==='All'||j.type===state.device);const count=s=>filtered.filter(j=>j.status===s).length;return `${header()}<main class="main"><button class="alert" data-action="new-jobs">${icon('bell')}<span class="grow"><strong>You have 3 new repair jobs</strong><p>New jobs have been assigned to you.</p></span><span class="chevron">›</span></button>${pageHeading('Technician Dashboard',"Good morning, Jordan!")}<div class="summary-grid">${[['To Do',count('To Do'),'note',''],['In Progress',count('In Progress'),'gear','teal'],['Recently Completed',count('Completed'),'check','green']].map(([title,n,i,c])=>`<button class="summary ${c}" data-action="summary" data-value="${title}">${tile(i)}<div><span class="summary-label">${title}</span><div class="metric">${n}<span>jobs</span></div>${title==='Recently Completed'?'<small>(last 7 days)</small>':''}</div><span class="chevron">›</span></button>`).join('')}<button class="summary wide orange" data-action="summary" data-value="Waiting">${tile('warning')}<div><span class="summary-label">Difficult / Transfer</span><div class="metric">${count('Waiting')}<span>jobs</span></div></div><span class="chevron">›</span></button><button class="summary wide" data-action="nav" data-page="help">${tile('help')}<div><h3>My Help</h3><small>Requests &amp; teamwork</small></div><span class="chevron">›</span></button></div><div class="section-head"><h2>Recent To-Do Jobs</h2><button class="text-button" data-action="summary" data-value="To Do">View All <span class="chevron">›</span></button></div><div class="jobs-list">${filtered.filter(j=>j.status==='To Do').slice(0,3).map(j=>jobRow(j)).join('')||empty('No to-do jobs','All caught up for this device type.')}</div><div class="report-banner">${tile('chart')}<div class="grow"><small>SAVE TIME, SEE YOUR IMPACT</small><h2>AI Work Report</h2><p class="muted">Your weekly and monthly summary.</p></div><button class="primary" data-action="nav" data-page="report">View Report →</button></div></main>${nav('dashboard')}`}
function empty(a,b='Try changing your filters.'){return `<div class="empty"><h3>${a}</h3><p>${b}</p></div>`}

function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),4000)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;handleAction(b.dataset.action,b,e)});


function select(name,options,value){return `<select name="${name}" data-filter="${name}" aria-label="${name}">${options.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select>`}
function myJobs(){const list=jobs.filter(j=>(state.device==='All'||j.type===state.device)&&(state.tab==='All Jobs'||j.status===state.tab)&&(state.priority==='All Priorities'||j.priority===state.priority)&&(state.status==='All Statuses'||j.status===state.status));const filtered=state.device!=='All'||state.priority!=='All Priorities'||state.status!=='All Statuses';return `${header()}<main class="main">${pageHeading('My Jobs','Your repairs, all in one place.')}<div class="pills job-tabs">${['All Jobs','In Progress','Waiting','Completed'].map(s=>`<button class="pill ${state.tab===s?'active':''}" data-action="job-tab" data-value="${s}">${s}</button>`).join('')}</div><details class="panel filters" ${state.filtersOpen||filtered?'open':''}><summary>Filters${filtered?' · Applied':''}</summary><div class="filter-content"><h3>Device Type</h3>${devicePills()}<div class="field-row"><label class="field">Priority${select('priority',['All Priorities','Low','Medium','High'],state.priority)}</label><label class="field">Status${select('status',['All Statuses',...statuses],state.status)}</label></div>${filtered?'<button class="text-button" data-action="clear-filters">Clear filters</button>':''}</div></details><div class="jobs-list">${list.map(j=>jobRow(j,true)).join('')||empty('No matching jobs')}</div></main>${nav('jobs')}`}
function info(i,label,value,sub=''){return `<div class="info">${tile(i)}<div><small>${label}</small><strong>${value}</strong>${sub?`<p>${sub}</p>`:''}</div></div>`}
function uploadControl(scope,label='Add Photos'){return `<label class="upload">${icon('upload')}<span>${label}</span><input type="file" accept="image/jpeg,image/png,image/webp" multiple data-upload="${scope}" aria-label="${label}"></label>`}
function imagesHTML(list,scope,editable=false){return list.map((a,i)=>`<div class="attachment"><button data-action="view-image" data-scope="${scope}" data-index="${i}" aria-label="View ${esc(a.name)}"><img src="${esc(a.src)}" alt="${esc(a.name)}"><span>${esc(a.name)}</span></button>${editable?`<button class="remove" data-action="remove-image" data-scope="${scope}" data-index="${i}" aria-label="Remove ${esc(a.name)}">×</button>`:''}</div>`).join('')}
function detail(){const j=job(),closed=['Completed','Awaiting Customer Confirmation'].includes(j.status);return `<main class="main"><button class="back" data-action="back-jobs">${icon('arrow')} Back to My Jobs</button><div class="page-heading detail-heading"><div><h1>Repair Job Detail</h1><p>#${j.id}</p></div>${badge(j.status)}</div><section class="panel details-grid">${info(j.type==='Phone'?'phone':j.type==='PC'?'pc':'appliance','Device Type',j.type,esc(j.device))}${info('user','Customer',esc(j.customer),'AC Mobile<br>Contact: '+esc(j.customer.toLowerCase().replaceAll(' ','.'))+'@example.com')}${info('jobs','Date Received','Mon, Apr 28, 2025','10:24 AM')}${info('warning','Priority',badge(j.priority))}${info('user','Assigned Technician','Jordan Smith')}${info('gear','Status',badge(j.status))}</section><section class="panel"><div class="panel-title">${tile('chat')}<h2>Customer Request</h2></div><p class="quote">${j.id==='RS-10482'?'“Screen is cracked and touch is not responding. Please replace the screen if possible. Need the data to be kept.”':`“${esc(j.issue)}. Please diagnose and repair the device. Keep my data safe.”`}</p></section><section class="panel"><div class="panel-title">${tile('note')}<h2 class="grow">Technician Notes</h2><button class="text-button" data-action="edit-note">${icon('edit')}${j.notes?'Edit':'Add Note'}</button></div><p class="quote">${esc(j.notes)||'No notes yet. Add your initial inspection and repair plan.'}</p></section><section class="panel"><div class="panel-title">${tile('clock')}<h2 class="grow">Work Log</h2><button class="secondary" data-action="add-log">＋ Add Log</button></div><ol class="timeline">${j.logs.map(l=>`<li><small>${esc(l.time)}</small><div><strong>${esc(l.title)}</strong><p>${esc(l.note)}</p></div></li>`).join('')}${!closed?`<li class="pending"><small></small><div><strong>${j.type==='Phone'?'Replace display module':'Complete repair'}</strong><p>Pending</p></div></li><li class="pending"><small></small><div><strong>Functional test</strong><p>Pending</p></div></li>`:''}</ol></section><section class="panel"><div class="panel-title">${tile('paperclip')}<h2>Attachments (${j.attachments.length})</h2></div><div class="attachments">${imagesHTML(j.attachments,'job')}${uploadControl('job','Add Photos')}</div></section><section class="panel"><div class="panel-title"><h2 class="grow">Personal Label</h2><button class="text-button" data-action="job-label">${icon('edit')} Edit</button></div>${j.label?badge(j.label,'label'):'<small>No personal label</small>'}</section>${j.shortages.length?`<section class="panel"><h2>Material Requests</h2>${j.shortages.map(s=>`<div class="insight"><div class="grow"><strong>${esc(s.type)}</strong><p>${esc(s.comment)}</p><small>${esc(s.time)} · Manager / Inventory · Simulated</small>${s.images.length?`<div class="attachments">${imagesHTML(s.images,'shortage-'+s.id)}</div>`:''}</div><div>${badge(s.fulfilled?'Resolved':'Waiting')}${!s.fulfilled?`<button class="text-button" data-action="material-arrived" data-id="${s.id}">Mark received<br>(simulation)</button>`:''}</div></div>`).join('')}</section>`:''}<div class="detail-actions">${j.status==='To Do'?'<button class="primary full" data-action="start-repair">Start Repair</button>':''}${j.status==='Waiting'?'<button class="primary full" data-action="resume-repair">Continue Repair</button>':''}${!closed?`<button class="action-card danger" data-action="shortage">${tile('warning')}<div class="grow"><strong>Shortage Material</strong><p>Report materials that are missing or needed for this repair.</p></div><span class="chevron">›</span></button><button class="primary full" data-action="complete-repair" ${j.status!=='In Progress'?'disabled':''}>${icon('check')}Repair Complete<small>(Awaiting Customer Confirmation)</small></button><button class="action-card" data-action="job-help">${tile('help')}<div><strong>Help</strong><p>Get assistance with this repair job</p></div></button>`:`<div class="panel"><div class="panel-title">${tile('check')}<h2>${j.status}</h2></div><p class="muted">${j.status==='Completed'?'The customer has confirmed the repair.':'The repair is finished. This job will be completed after the customer confirms the result.'}</p>${j.status==='Awaiting Customer Confirmation'?'<button class="text-button" data-action="simulate-confirm">Simulate customer confirmation</button>':''}</div>`}</div></main>${nav('jobs')}`}
let selectedTech=0,helpDraft='',helpPhotos=[],materialPhotos=[],lastFocus=null,materialDraft={type:'Replacement Part',comment:''};
function helpForJob(){const j=job();return `<main class="main"><button class="back" data-action="back-job">${icon('arrow')} Back to Job</button><div class="page-heading"><div><h1>Help for Job #${j.id}</h1><p>Get help from other technicians at your store or nearby stores.</p></div></div><section class="panel help-summary">${info('phone',esc(j.device),'Device')}${info('note',esc(j.issue),'Issue Summary')}<div>${badge(j.status)}<p class="muted">Current Status</p></div><div><strong>#${j.id}</strong><p class="muted">Job ID</p></div></section><div class="section-head"><h2>Recommended Technicians</h2><button class="text-button" data-action="capacity-info">ⓘ How it works?</button></div><p class="muted" style="font-size:.9rem">Technicians from your store and nearby stores who can help with this issue.</p><div class="tech-list">${techs.map((t,i)=>`<label class="tech ${i===selectedTech?'selected':''}"><input type="radio" name="technician" value="${i}" ${selectedTech===i?'checked':''} ${t.active>=t.max?'disabled':''}><img class="avatar" src="assets/technician-${i}.png" alt="${t.name}"><div class="tech-name"><strong>${t.name}</strong>${badge(t.level,t.level==='Gold'?'medium':'')}<small>${t.specialty}</small></div><div class="tech-store"><p>⌖ ${t.store}</p><small>${t.distance} away</small></div><div class="rating"><span>★</span> ${t.rating}</div><div class="capacity"><strong>${t.active}/${t.max}</strong><div class="progress-track"><i style="width:${t.active/t.max*100}%"></i></div><small>active requests</small></div></label>`).join('')}</div><div class="panel capacity-note">${tile('help')}<p>Regular technicians can accept up to <strong>4</strong> help requests.<br>Gold technicians can accept up to <strong>6</strong> help requests.</p></div><form id="help-request-form" class="panel"><h2>Explain the Problem</h2><p class="muted" style="font-size:.88rem;margin:7px 0 10px">Share any details that will help the selected technician.</p><label class="sr-only" for="problem">Explain the Problem</label><textarea id="problem" name="problem" required maxlength="500" placeholder="Describe the issue, what you’ve already tried, and what kind of help you need…">${esc(helpDraft)}</textarea><div class="char-count" id="problem-count">${helpDraft.length}/500</div><h3 style="margin:16px 0 10px">Add Photos <small>(Optional)</small></h3><div class="attachments" id="help-photos">${imagesHTML(helpPhotos,'help',true)}${uploadControl('help','Add more')}</div><small style="display:block;margin:10px 0 15px">JPG, PNG or WebP · Up to 10 MB each · Up to 10 photos</small><button class="primary full" type="submit" ${['Completed','Awaiting Customer Confirmation'].includes(j.status)?'disabled':''}>${icon('send')} Send Help Request</button></form><div class="panel capacity-note">${tile('help')}<p>After you send the request, this job will be updated to ${badge('Waiting')}. The notification is simulated in this prototype.</p></div></main>`}
function requestList(){let list=requests.filter(r=>r.mode===state.helpMode&&(state.helpStatus==='All'||r.status===state.helpStatus)&&(state.helpStore==='All Stores'||r.store===state.helpStore)&&(state.helpTech==='All Technicians'||r.tech===state.helpTech)&&[r.jobId,r.tech,jobs.find(j=>j.id===r.jobId)?.device,jobs.find(j=>j.id===r.jobId)?.issue].join(' ').toLowerCase().includes(state.search.toLowerCase()));list.sort((a,b)=>state.oldest?new Date(a.created)-new Date(b.created):new Date(b.created)-new Date(a.created));return list.map(requestCard).join('')||empty('No matching help requests')}
function myHelp(){return `${header()}<main class="main">${pageHeading('My Help','Help with repairs. Support from your team.')}<div class="segmented"><button class="${state.helpMode==='sent'?'active':''}" data-action="help-mode" data-value="sent">I Asked for Help</button><button class="${state.helpMode==='received'?'active':''}" data-action="help-mode" data-value="received">Others Asked Me</button></div><div class="pills help-tabs">${['All','Open','Waiting','Resolved','Completed'].map(s=>`<button class="pill ${state.helpStatus===s?'active':''}" data-action="help-status" data-value="${s}">${s}</button>`).join('')}</div><div id="request-list">${requestList()}</div></main>${nav('more')}`}
function initials(s){return s.split(' ').map(x=>x[0]).slice(0,2).join('')}
function requestCard(r){const j=jobs.find(j=>j.id===r.jobId);return `<article class="request"><button class="request-header" data-action="open-help" data-id="${r.id}">${deviceIcon(j)}<span><strong class="job-id">#${r.jobId}</strong><span class="job-device">${esc(j.device)}</span></span><span class="issue">${esc(j.issue)}</span><span class="request-status">${badge(r.status)}<small style="display:block;margin-top:5px">${new Date(r.created).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</small></span><span class="chevron">›</span></button></article>`}
function helpDetail(){
  const r=requests.find(r=>r.id===route().id);
  const back=`<button class="back" data-action="nav" data-page="help">${icon('arrow')} Back to My Help</button>`;
  if(!r)return `${header()}<main class="main">${back}${pageHeading('Help Detail','')}${empty('Help request not found','Return to My Help to choose a request.')}</main>${nav('more')}`;
  if(state.helpMode!==r.mode){state.helpMode=r.mode;state.helpStatus='All';}
  const j=jobs.find(j=>j.id===r.jobId);
  return `${header()}<main class="main">${back}${pageHeading('Help Detail',r.mode==='sent'?'I Asked for Help':'Others Asked Me')}<article class="request help-detail"><div class="request-header">${deviceIcon(j)}<span><strong class="job-id">#${r.jobId}</strong><span class="job-device">${esc(j.device)}</span></span><span class="issue">${esc(j.issue)}</span><span class="request-status">${badge(r.status)}<small style="display:block;margin-top:5px">${new Date(r.created).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</small></span></div><div class="request-body"><div class="request-meta"><div>${r.mode==='sent'?'Asked For Help':'Requested By'}<p>${esc(r.tech)}<br>(Technician)</p></div><div>Store<p>${esc(r.store)}</p></div><div>Created<p>${new Date(r.created).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'})}</p></div></div><h3>Conversation</h3><div class="conversation">${r.comments.map(c=>`<div class="message ${c.author!=='You'?'other':''}"><span class="avatar">${c.author==='You'?'JS':esc(initials(c.author))}</span><div class="grow"><strong>${esc(c.author)}</strong><p class="bubble">${esc(c.text)}</p><time>${esc(c.time)}</time></div></div>`).join('')}</div>${r.photos?.length?`<div class="attachments">${imagesHTML(r.photos,'request-'+r.id)}</div>`:''}<label for="comment-${r.id}"><h3>Add a Comment</h3></label><form class="comment-form" data-request-id="${r.id}"><input id="comment-${r.id}" name="comment" maxlength="1000" required placeholder="Write a message to ${esc(r.tech.split(' ')[0])}…"><button class="primary" type="submit">Send</button></form><div class="appreciation"><button data-action="appreciation" data-id="${r.id}" ${r.appreciated?'disabled':''}>${icon('star')}<span><strong>${r.appreciated?'Appreciation Sent':'Send Appreciation'}</strong><small style="display:block;margin-top:4px">Recognize great help and teamwork!</small></span></button></div>${!['Resolved','Completed'].includes(r.status)?`<button class="secondary full" style="margin-top:12px" data-action="resolve-help" data-id="${r.id}">${r.mode==='received'?'Mark Assistance Resolved':'Mark as Resolved'}</button>`:r.status==='Resolved'?`<button class="text-button" style="margin-top:10px" data-action="close-help" data-id="${r.id}">Complete Help Request</button>`:''}<button class="text-button" style="margin-top:12px" data-action="job" data-id="${r.jobId}">View Repair Job →</button></div></article></main>${nav('more')}`;
}
function reportData(){const r={...reports[state.period]};if(state.periodOffset===-1){Object.assign(r,state.period==='Weekly'?{completed:10,turnaround:'2.9',sent:2,collaboration:85,confirmation:92,values:[1,1,2,2,1,2,1],labels:['Apr 14','Apr 15','Apr 16','Apr 17','Apr 18','Apr 19','Apr 20'],range:'Apr 14 – Apr 20, 2025'}:{completed:40,turnaround:'3.1',sent:8,collaboration:83,confirmation:91,values:[8,11,9,12],range:'Mar 1 – Mar 31, 2025'});}return r}
function report(){const r=reportData();return `<main class="main"><div class="report-header"><button class="back" data-action="nav" data-page="dashboard" aria-label="Back to Dashboard">${icon('arrow')}</button><h1>AI Work Report</h1><p>Your work, summarized by AI from completed jobs,<br>help requests, and team interactions.</p></div><div class="report-controls"><div class="segmented">${['Weekly','Monthly'].map(s=>`<button class="${state.period===s?'active':''}" data-action="period" data-value="${s}">${s}</button>`).join('')}</div><button class="secondary" data-action="report-date">${icon('jobs')} &nbsp; ${r.range} &nbsp; ›</button></div><div class="report-metrics">${[['note','Completed Jobs',r.completed,'20%'],['clock','Avg. Turnaround',r.turnaround+' hours','18% faster'],['chat','Help Requests Sent',r.sent,'40%'],['team','Collaboration Score',r.collaboration+'/100','8%'],['check','Customer Confirmation Rate',r.confirmation+'%','6%']].map(([i,l,v,c])=>`<div class="report-metric">${tile(i)}<p>${l}</p><strong>${String(v).replace(' hours',' <span class="unit">hours</span>')}</strong><span class="change">↑ ${c}</span><small>vs. previous ${r.previous}</small></div>`).join('')}</div><section class="panel"><div class="section-head" style="margin:0"><h2>Completed Jobs Trend</h2><strong>${r.completed} jobs <span style="color:#009c34;font-size:.85rem"> ↑ 20%</span></strong></div><div class="chart" role="img" aria-label="Completed jobs: ${r.labels.map((l,i)=>l+': '+r.values[i]).join(', ')}">${r.values.map((v,i)=>`<div class="chart-col"><div class="bar" style="height:${v/Math.max(...r.values)*88}%"><em>${v}</em></div><small>${r.labels[i]}</small></div>`).join('')}</div></section><section class="panel"><div class="panel-title">${tile('spark')}<div><h2>AI Insights</h2><small>Based on your repair data, help activity, and team interactions.</small></div></div>${[['chart','Strong completion rate',`You completed ${r.completed} jobs this ${r.previous}. Great momentum!`,'Your completed repairs are distributed across the period in the chart above. Compare the previous period to review your workload.'],['help','Most help requests: Power & Battery','47% of your help requests were about power or battery issues. Consider reviewing the latest troubleshooting guide.','Battery and charging diagnostics are a recurring challenge in this sample report. Review connector checks, battery health, and power tests with a specialist.'],['team','Great collaboration',`You frequently assisted ${state.period==='Weekly'?4:12} other technicians this ${r.previous}. Your support helps the team succeed!`,'Your team contributions include diagnostic comments, shared repair notes, and resolved help requests.']].map(([i,t,p,d],n)=>`<button class="insight" data-action="insight" data-index="${n}" aria-expanded="false">${tile(i)}<div class="grow"><h3>${t}</h3><p>${p}</p></div><span class="chevron">›</span></button><p id="insight-${n}" class="insight-detail" hidden>${d}</p>`).join('')}</section><section class="panel"><div class="panel-title">${tile('chat')}<div class="grow"><h2>Comments & Recognition</h2><small>From customers and your team this ${r.previous}.</small></div><button class="text-button" data-action="recognition">View All (6) ›</button></div><div class="recognition"><blockquote>“Great service! Fixed my phone quickly and explained everything clearly.”<cite>— Customer</cite></blockquote><blockquote>“Thanks for helping me with the diagnostic on that washer. Really appreciate it!”<cite>— Alex Chen, Technician</cite></blockquote></div></section><div class="report-actions"><button class="secondary" data-action="nav" data-page="dashboard">Close</button><button class="primary" data-action="download-report">${icon('download')} Download Report</button></div><p class="prototype-note">PDF · Includes charts, insights and details<br>Prototype report · Sample data, no live AI service</p></main>`}
function messages(){const items=[...requests].sort((a,b)=>new Date(b.created)-new Date(a.created)).flatMap(r=>[...r.comments].reverse().map(c=>({r,c})));return `${header()}<main class="main">${pageHeading('Messages','Updates from your team.')}<div class="message-feed" role="list">${items.map(({r,c})=>`<article class="message-card" role="listitem"><span class="avatar">${c.author==='You'?'JS':esc(initials(c.author))}</span><div class="grow"><div class="message-heading"><strong>${esc(c.author)}</strong><time>${esc(c.time)}</time></div><span class="message-job">#${r.jobId}${c.author==='You'?' · To '+esc(r.tech):''}</span><p>${esc(c.text)}</p></div></article>`).join('')||empty('No messages yet','Team updates will appear here.')}</div></main>${nav('messages')}`}
function render(){const p=route().page;const pages={dashboard,jobs:myJobs,job:detail,'job-help':helpForJob,help:myHelp,'help-detail':helpDetail,report,messages};$('#app').innerHTML=`<div class="shell">${(pages[p]||dashboard)()}</div>`;document.title='FixFlow | '+({dashboard:'Technician Dashboard',jobs:'My Jobs',job:'Repair Job Detail','job-help':'Help for Job',help:'My Help','help-detail':'Help Detail',report:'AI Work Report',messages:'Messages'}[p]||'Technician Dashboard')}
function now(){return new Date().toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}
function addLog(j,title,note=''){j.logs.push({title,note,time:now()});j.updated=now()}
function transition(j,status,title){j.status=status;j.updated=now();if(status==='In Progress'&&j.progress===0)j.progress=10;if(['Completed','Awaiting Customer Confirmation'].includes(status))j.progress=100;addLog(j,title);saveSession();render()}
function saveSession(){try{sessionStorage.setItem('fixflow-prototype-v1',JSON.stringify({jobs,requests,labels,techs}));}catch{toast('Browser storage is full. Changes remain available until this page reloads.')}}
function restoreSession(){try{const d=JSON.parse(sessionStorage.getItem('fixflow-prototype-v1')||'null');if(d?.jobs?.length){jobs=d.jobs;requests=d.requests;labels=d.labels;d.techs?.forEach((t,i)=>{if(techs[i])techs[i].active=t.active})}}catch{}}
function openSheet(title,body){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title" tabindex="-1"><div class="handle"></div><div class="sheet-head"><h2 id="sheet-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}</section></div>`;document.body.style.overflow='hidden';$('.sheet').focus()}
function closeSheet(){if($('#shortage-comment')){materialDraft.comment=$('#shortage-comment').value;materialDraft.type=$('input[name="materialType"]:checked')?.value||materialDraft.type}$('#modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.isConnected&&lastFocus.focus()}
function shortageSheet(){const j=job();openSheet('Shortage Material',`<p class="muted">Report materials that are missing or needed for this repair.</p><div class="action-card" style="margin:18px 0">${tile('phone')}<div><strong>Job #${j.id}</strong><p>${esc(j.device)} &nbsp; | &nbsp; Customer: ${esc(j.customer)}</p></div></div><form id="shortage-form"><h3>Material Type</h3><p class="muted" style="font-size:.85rem;margin-top:7px">Select the type of material you need.</p><div class="material-grid">${['Replacement Part','Screw / Small Part','Adhesive','Tool / Equipment','Consumable','Other'].map(t=>`<label class="material-option"><input type="radio" name="materialType" value="${t}" ${materialDraft.type===t?'checked':''}>${t}</label>`).join('')}</div><label class="field">Comment<textarea id="shortage-comment" name="comment" maxlength="500" required placeholder="Describe the missing material, model, and why it is needed…">${esc(materialDraft.comment)}</textarea></label><label style="display:flex;gap:9px;align-items:center;font-size:.85rem"><input type="checkbox" name="blocked" checked style="width:17px;min-height:17px;accent-color:#167aff">This shortage prevents me from continuing the repair</label><h3 style="margin:20px 0 12px">Upload Images <small>(Optional)</small></h3><div id="material-photos" class="attachments">${imagesHTML(materialPhotos,'material',true)}${uploadControl('material','Add Photos (up to 10)')}</div><button class="primary full" type="submit">Submit Request</button><p class="prototype-note">Request to Manager / Inventory is simulated.</p></form>`)}
function listForScope(scope){if(scope==='job')return job().attachments;if(scope==='help')return helpPhotos;if(scope==='material')return materialPhotos;if(scope.startsWith('request-'))return requests.find(r=>r.id===scope.slice(8))?.photos||[];if(scope.startsWith('shortage-'))return job().shortages.find(s=>s.id===scope.slice(9))?.images||[];return []}
function handleAction(a,b){const j=job(),v=b.dataset.value;
if(a==='nav'){if(b.dataset.page==='more'){openSheet('More',`<div class="sheet-menu"><button data-action="nav" data-page="help">${icon('help')} My Help <span class="grow"></span>›</button><button data-action="nav" data-page="report">${icon('chart')} AI Work Report <span class="grow"></span>›</button><button data-action="profile">${icon('user')} My Profile <span class="grow"></span>›</button></div>`)}else{closeSheet();if(b.dataset.page==='jobs'){state.tab='All Jobs';state.status='All Statuses';}go(b.dataset.page)}return}
if(a==='clear-filters'){state.device='All';state.priority='All Priorities';state.status='All Statuses';state.filtersOpen=false;render()}
else if(a==='device'){state.device=v;state.filtersOpen=true;render()}
else if(a==='job'){closeSheet();go('job',b.dataset.id)}
else if(a==='back-jobs'){state.tab='All Jobs';state.status='All Statuses';state.device='All';state.label='';state.priority='All Priorities';go('jobs')}
else if(a==='back-job')go('job',j.id);
else if(a==='new-jobs'||a==='summary'){closeSheet();state.tab='All Jobs';state.device='All';state.priority='All Priorities';state.label='';state.status=a==='new-jobs'?'To Do':v==='Recently Completed'?'Completed':v;go('jobs')}
else if(a==='job-tab'){state.tab=v;state.status='All Statuses';render()}
else if(a==='label-filter'){state.label=state.label===v?'':v;render()}
else if(a==='add-label'){openSheet('Add Personal Label',`<form id="label-form"><label class="field">Label name<input name="label" required maxlength="35" placeholder="e.g. Parts ordered"></label><p class="muted">Labels help organize jobs. They do not change a job’s status.</p><button type="submit" class="primary full">Add Label</button></form>`)}
else if(a==='job-label'){openSheet('Edit Personal Label',`<form id="job-label-form"><label class="field">Personal label<select name="label"><option value="">No label</option>${labels.map(l=>`<option ${j.label===l?'selected':''}>${esc(l)}</option>`).join('')}</select></label><button class="primary full" type="submit">Save Label</button></form>`)}
else if(a==='start-repair'){if(j.status==='To Do'){transition(j,'In Progress','Repair started');toast('Repair started. Status: In Progress.')}}
else if(a==='resume-repair'){if(j.status==='Waiting'){transition(j,'In Progress','Repair resumed','');toast('Repair resumed. Status: In Progress.')}}
else if(a==='edit-note')openSheet(j.notes?'Edit Technician Notes':'Add Technician Note',`<form id="note-form"><label class="field">Technician Notes<textarea name="note" required maxlength="3000" rows="6">${esc(j.notes)}</textarea></label><button class="primary full" type="submit">Save Note</button></form>`);
else if(a==='add-log'){const dt=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);openSheet('Add Work Log',`<form id="log-form"><label class="field">Operation<input name="operation" required maxlength="120" placeholder="e.g. Initial inspection completed"></label><label class="field">Time<input name="time" type="datetime-local" value="${dt}" required></label><label class="field">Description<textarea name="description" maxlength="1000" placeholder="What did you do? What did you find?"></textarea></label><label class="field">Progress (%)<input name="progress" type="number" min="0" max="100" value="${j.progress}" required></label><p class="muted" style="font-size:.8rem">A 100% work log does not complete the job. Use Repair Complete after testing.</p><div style="margin-top:12px">${uploadControl('job','Attach photo')}</div><button type="submit" class="primary full">Add Log</button></form>`)}
else if(a==='material-arrived'){const s=j.shortages.find(s=>s.id===b.dataset.id);s.fulfilled=true;addLog(j,'Materials received (simulation)',s.type);saveSession();render();toast('Materials received. You can continue the repair.')}
else if(a==='shortage')shortageSheet();
else if(a==='complete-repair'&&j.status==='In Progress')openSheet('Repair Complete',`<p>The repair will move to <strong>Awaiting Customer Confirmation</strong>. It will only become Completed after the customer confirms the result.</p><button class="primary full" data-action="confirm-repair">Confirm Repair Complete</button>`);
else if(a==='confirm-repair'&&j.status==='In Progress'){closeSheet();transition(j,'Awaiting Customer Confirmation','Repair completed — awaiting customer confirmation');toast('Repair submitted. Awaiting Customer Confirmation.')}
else if(a==='simulate-confirm'&&j.status==='Awaiting Customer Confirmation'){transition(j,'Completed','Customer confirmed the repair (simulation)');toast('Customer confirmation simulated. Job Completed.')}
else if(a==='job-help'){selectedTech=techs.findIndex(t=>t.active<t.max);helpDraft='';helpPhotos=[];go('job-help',j.id)}
else if(a==='capacity-info')openSheet('How recommendations work',`<p>Technicians are shown by specialty, store, distance, rating and current workload.</p><div class="panel"><p><strong>Gold Technician:</strong> up to 6 active help requests.<br><strong>Regular Technician:</strong> up to 4 active help requests.</p></div><p>A technician at capacity cannot be selected. Recommendations and distances are sample data in this prototype.</p>`);
else if(a==='help-mode'){state.helpMode=v;state.helpStatus='All';state.helpStore='All Stores';state.helpTech='All Technicians';state.search='';render()}
else if(a==='help-status'){state.helpStatus=v;render()}
else if(a==='help-sort'){state.oldest=!state.oldest;render()}
else if(a==='open-help'){go('help-detail',b.dataset.id)}
else if(a==='help-metric'){if(v==='Team Support'){state.helpMode='received';state.helpStatus='All'}else if(v==='Appreciation Sent'){openSheet('Appreciation Sent',requests.filter(r=>r.appreciated).map(r=>`<div class="panel">${icon('star')} ${esc(r.tech)} · #${r.jobId}</div>`).join('')||empty('No appreciation sent yet','Thank a teammate in a help conversation.'));return}else{state.helpStatus=v==='Open Requests'?'Open':'Resolved'}render()}
else if(['appreciation','praise'].includes(a)){const r=requests.find(x=>x.id===b.dataset.id);r[a==='praise'?'praised':'appreciated']=true;r.comments.push({author:'You',text:a==='praise'?'Great work! Thank you for sharing your expertise.':'Thank you for your help and teamwork!',time:now()});saveSession();render();toast(a==='praise'?'Praise sent.':'Appreciation sent.')}
else if(a==='resolve-help'||a==='close-help'){const r=requests.find(x=>x.id===b.dataset.id);r.status=a==='resolve-help'?'Resolved':'Completed';if(r.techIndex!==undefined&&!r.capacityReleased){techs[r.techIndex].active=Math.max(0,techs[r.techIndex].active-1);r.capacityReleased=true;}r.comments.push({author:'You',text:a==='resolve-help'?'This help request has been resolved.':'This help request is complete.',time:now()});saveSession();render();toast('Help request '+r.status.toLowerCase()+'.')}
else if(a==='open-conversation'){const r=requests.find(x=>x.id===b.dataset.id);state.helpMode=r.mode;state.helpStatus='All';state.helpStore='All Stores';state.helpTech='All Technicians';state.search='';go('help-detail',r.id)}
else if(a==='period'){state.period=v;state.periodOffset=0;render()}
else if(a==='report-date')openSheet('Report Period',`<div class="sheet-menu"><button data-action="set-period-date" data-value="0">${reports[state.period].range}</button><button data-action="set-period-date" data-value="-1">${state.period==='Weekly'?'Apr 14 – Apr 20, 2025':'Mar 1 – Mar 31, 2025'}</button></div>`);
else if(a==='set-period-date'){state.periodOffset=Number(v);closeSheet();render()}
else if(a==='insight'){const el=$('#insight-'+b.dataset.index);el.hidden=!el.hidden;b.setAttribute('aria-expanded',String(!el.hidden))}
else if(a==='recognition')openSheet('Comments & Recognition',`<div class="recognition" style="grid-template-columns:1fr">${['Great service! Fixed my phone quickly and explained everything clearly.','Thanks for helping me with the diagnostic on that washer. Really appreciate it!','Clear updates throughout the repair.','Excellent troubleshooting on the battery issue.','Thank you for checking the display connector with me.','Great teamwork this week!'].map((c,i)=>`<blockquote>“${c}”<cite>— ${i%2?'Technician':'Customer'}</cite></blockquote>`).join('')}</div>`);
else if(a==='download-report'){downloadReport()}
else if(a==='notifications')openSheet('Notifications',`<div class="sheet-menu"><button data-action="new-jobs">${icon('bell')}You have 3 new repair jobs. View jobs →</button><button data-action="nav" data-page="messages">${icon('chat')}View your team conversations →</button></div><p class="prototype-note">Prototype notifications · No live notification service</p>`);
else if(a==='profile')openSheet('Jordan Smith',`<div class="info" style="margin:20px 0"><span class="avatar">JS</span><div><h3>Technician</h3><p class="muted">Downtown Store · Regular Technician</p></div></div><p>FixFlow · Week 7 technician prototype</p><p>Changes are kept in this browser tab for your testing session. No customer, manager or live AI service is connected.</p><button class="secondary full" data-action="reset-demo">Reset Prototype Session</button>`);
else if(a==='reset-demo')openSheet('Reset Prototype Session',`<p>This resets only this prototype’s sample jobs, notes, uploads and help conversations to their initial state.</p><button class="primary full" data-action="confirm-reset">Reset Demo Data</button>`);
else if(a==='confirm-reset'){sessionStorage.removeItem('fixflow-prototype-v1');location.hash='#dashboard';location.reload()}
else if(a==='close-modal')closeSheet();
else if(a==='view-image'){const list=listForScope(b.dataset.scope),img=list[Number(b.dataset.index)];if(img)openSheet(esc(img.name),`<img class="image-viewer" src="${esc(img.src)}" alt="${esc(img.name)}">`)}
else if(a==='remove-image'){listForScope(b.dataset.scope).splice(Number(b.dataset.index),1);refreshUploads(b.dataset.scope)}
}
function refreshUploads(scope){if(scope==='material')$('#material-photos').innerHTML=imagesHTML(materialPhotos,scope,true)+uploadControl(scope,'Add Photos (up to 10)');else if(scope==='help')$('#help-photos').innerHTML=imagesHTML(helpPhotos,scope,true)+uploadControl(scope,'Add more');else{saveSession();if(!$('.sheet'))render()}}
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.filter){state[el.dataset.filter]=el.value;state.filtersOpen=true;render()}if(el.name==='technician'){selectedTech=Number(el.value);document.querySelectorAll('.tech').forEach((t,i)=>t.classList.toggle('selected',i===selectedTech))}if(el.dataset.upload){const scope=el.dataset.upload,list=listForScope(scope);for(const file of el.files){if(list.length>=10){toast('You can add up to 10 images.');break}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('Choose a JPG, PNG or WebP image under 10 MB.');continue}try{const src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});list.push({src,name:file.name})}catch{toast('Unable to read that image. Please try another file.')}}refreshUploads(scope);if(scope==='job')toast('Image attached to the repair job.')}});
document.addEventListener('input',e=>{if(e.target.id==='problem'){helpDraft=e.target.value;$('#problem-count').textContent=helpDraft.length+'/500'}if(e.target.id==='help-search'){state.search=e.target.value;$('#request-list').innerHTML=requestList()}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,fd=new FormData(form),j=job();if(!form.reportValidity())return;
if(form.id==='note-form'){const note=String(fd.get('note')).trim();if(!note)return toast('Please enter a note.');j.notes=note;addLog(j,'Technician notes updated');closeSheet();saveSession();render();toast('Technician note saved.')}
else if(form.id==='log-form'){const title=String(fd.get('operation')).trim();if(!title)return toast('Please enter an operation.');j.logs.push({title,time:new Date(fd.get('time')).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}),note:String(fd.get('description')).trim()});j.progress=Number(fd.get('progress'));j.updated=now();closeSheet();saveSession();render();toast('Work log added.')}
else if(form.id==='label-form'){const l=String(fd.get('label')).trim();if(!l)return toast('Please enter a label.');if(labels.some(x=>x.toLowerCase()===l.toLowerCase()))return toast('This label already exists.');labels.push(l);closeSheet();saveSession();render();toast('Personal label added.')}
else if(form.id==='job-label-form'){j.label=String(fd.get('label'));j.updated=now();closeSheet();saveSession();render();toast('Job label saved.')}
else if(form.id==='shortage-form'){const comment=String(fd.get('comment')).trim();if(!comment)return toast('Please describe the missing material.');j.shortages.push({id:crypto.randomUUID(),type:String(fd.get('materialType')),comment,images:[...materialPhotos],time:now(),fulfilled:false});addLog(j,'Material shortage reported',comment);if(fd.get('blocked'))j.status='Waiting';closeSheet();materialDraft={type:'Replacement Part',comment:''};materialPhotos=[];saveSession();render();toast('Shortage request submitted (simulation).'+(j.status==='Waiting'?' Job status: Waiting.':''))}
else if(form.id==='help-request-form'){const t=techs[selectedTech],problem=String(fd.get('problem')).trim();if(!problem)return toast('Please explain the problem.');if(!t||t.active>=t.max)return toast('Please select a technician with available capacity.');if(['Completed','Awaiting Customer Confirmation'].includes(j.status))return toast('This repair is already finished.');const r={id:'help-'+crypto.randomUUID(),jobId:j.id,mode:'sent',tech:t.name,techIndex:selectedTech,store:t.store,status:'Waiting',created:new Date().toISOString(),photos:[...helpPhotos],comments:[{author:'You',text:problem,time:now()}]};requests.unshift(r);t.active++;j.status='Waiting';addLog(j,'Help requested from '+t.name,problem);state.helpMode='sent';state.helpStatus='All';state.helpStore='All Stores';state.helpTech='All Technicians';state.search='';helpDraft='';helpPhotos=[];saveSession();go('help-detail',r.id);toast('Help request sent (simulation). Job status: Waiting.')}
else if(form.dataset.requestId){const text=String(fd.get('comment')).trim();if(!text)return toast('Please enter a comment.');const r=requests.find(r=>r.id===form.dataset.requestId);r.comments.push({author:'You',text,time:now()});saveSession();render();toast('Comment added to the conversation.')}
});
document.addEventListener('keydown',e=>{const sheet=$('.sheet');if(!sheet)return;if(e.key==='Escape'){e.preventDefault();closeSheet()}if(e.key==='Tab'){const items=[...sheet.querySelectorAll('button:not([disabled]),a,input:not([type="file"]),textarea,select')].filter(x=>x.offsetParent!==null);const first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===sheet)){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-overlay'))closeSheet()});
function downloadReport(){const r=reportData();const lines=['FixFlow - AI Work Report',state.period+' | '+r.range,'Prototype report - sample data','',`Completed Jobs: ${r.completed}`,`Average Turnaround: ${r.turnaround} hours`,`Help Requests Sent: ${r.sent}`,`Collaboration Score: ${r.collaboration}/100`,`Customer Confirmation Rate: ${r.confirmation}%`,'','Completed Jobs Trend',...r.labels.map((l,i)=>`${l}: ${r.values[i]} jobs`),'','AI Insights',`Strong completion rate: ${r.completed} completed repairs this ${r.previous}.`,'Most help requests: Power & Battery (47% of sample requests).','Great collaboration: support from your team helps repairs move forward.','','Comments & Recognition','Great service! Fixed my phone quickly and explained everything clearly.','Thanks for helping me with the diagnostic on that washer.'];const safe=s=>s.replace(/[^\x20-\x7E]/g,'-').replace(/[\\()]/g,'\\$&');let stream='BT /F1 18 Tf 45 798 Td ('+safe(lines[0])+') Tj /F1 11 Tf ';for(const l of lines.slice(1))stream+='0 -23 Td ('+safe(l)+') Tj ';stream+='ET\n';r.values.forEach((v,i)=>{stream+=`0.1 0.48 1 rg ${55+i*65} 105 40 ${v/Math.max(...r.values)*95} re f\n`});stream+='0 0 0 rg BT /F1 10 Tf 45 80 Td (Completed repairs by '+(state.period==='Weekly'?'day':'week')+' - '+r.values.join(', ')+') Tj ET';const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Length '+stream.length+' >>\nstream\n'+stream+'\nendstream'];let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((o,i)=>{offsets.push(pdf.length);pdf+=(i+1)+' 0 obj\n'+o+'\nendobj\n'});const xref=pdf.length;pdf+='xref\n0 '+(objects.length+1)+'\n0000000000 65535 f \n'+offsets.slice(1).map(o=>String(o).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size '+(objects.length+1)+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF';const url=URL.createObjectURL(new Blob([pdf],{type:'application/pdf'}));const a=document.createElement('a');a.href=url;a.download=`FixFlow-${state.period}-Report.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Your PDF report has been downloaded.')}
restoreSession();window.addEventListener('hashchange',()=>{closeSheet();render();window.scrollTo(0,0)});render();
if(document.modelContext?.registerTool){const tools=[{name:'list_repair_jobs',title:'List repair jobs',description:'Read the prototype repair jobs and current statuses.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({jobs:jobs.map(({id,device,status,priority,progress})=>({id,device,status,priority,progress}))})},{name:'open_repair_job',title:'Open repair job',description:'Navigate to the detail page for an existing job. Does not change repair status.',inputSchema:{type:'object',properties:{jobId:{type:'string'}},required:['jobId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async(input)=>{if(!input||typeof input.jobId!=='string'||!jobs.some(j=>j.id===input.jobId))throw new Error('Unknown repair job');location.hash='#job/'+input.jobId;render();return {jobId:input.jobId,status:jobs.find(j=>j.id===input.jobId).status,page:'Repair Job Detail'}}}];for(const t of tools){try{Promise.resolve(document.modelContext.registerTool(t)).catch(()=>{})}catch{}}}
